create table if not exists public.platform_tenant_limits(clinica_id uuid primary key references public.clinicas(id)on delete cascade,max_users integer not null default 20 check(max_users>0),max_ai_tokens integer not null default 100000 check(max_ai_tokens>=0),max_notifications integer not null default 5000 check(max_notifications>=0),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));alter table public.platform_tenant_limits enable row level security;create policy "plataforma gerencia limites"on public.platform_tenant_limits for all to authenticated using(public.is_platform_admin())with check(public.is_platform_admin());
create or replace function public.platform_usage_overview()returns jsonb language plpgsql stable security definer set search_path=public as $$begin if not is_platform_admin()then raise exception'Acesso restrito';end if;return jsonb_build_object('generated_at',now(),'clinics',coalesce((select jsonb_agg(to_jsonb(x)order by x.clinica_nome)from(select c.id clinica_id,c.nome clinica_nome,coalesce(l.max_users,20)max_users,(select count(*)from profiles p where p.clinica_id=c.id and p.ativo)users_used,coalesce(l.max_ai_tokens,100000)max_ai_tokens,(select coalesce(sum(a.input_tokens+a.output_tokens),0)from platform_ai_usage a where a.clinica_id=c.id and a.created_at>=date_trunc('month',now()))ai_tokens_used,coalesce(l.max_notifications,5000)max_notifications,(select count(*)from notification_queue n where n.clinica_id=c.id and n.created_at>=date_trunc('month',now()))notifications_used from clinicas c left join platform_tenant_limits l on l.clinica_id=c.id)x),'[]'::jsonb));end;$$;
create or replace function public.platform_set_tenant_limits(p_clinica_id uuid,p_max_users integer,p_max_ai_tokens integer,p_max_notifications integer)returns void language plpgsql security definer set search_path=public as $$begin if not is_platform_admin()then raise exception'Acesso restrito';end if;if p_max_users<1 or p_max_ai_tokens<0 or p_max_notifications<0 then raise exception'Limites inválidos';end if;insert into platform_tenant_limits(clinica_id,max_users,max_ai_tokens,max_notifications,updated_by)values(p_clinica_id,p_max_users,p_max_ai_tokens,p_max_notifications,auth.uid())on conflict(clinica_id)do update set max_users=excluded.max_users,max_ai_tokens=excluded.max_ai_tokens,max_notifications=excluded.max_notifications,updated_at=now(),updated_by=auth.uid();insert into audit_log(user_id,clinica_id,action,collection,record_id,changes)values(auth.uid(),p_clinica_id,'update','platform_tenant_limits',p_clinica_id::text,jsonb_build_object('users',p_max_users,'ai_tokens',p_max_ai_tokens,'notifications',p_max_notifications));end;$$;
revoke all on function public.platform_usage_overview(),public.platform_set_tenant_limits(uuid,integer,integer,integer)from public,anon;grant execute on function public.platform_usage_overview(),public.platform_set_tenant_limits(uuid,integer,integer,integer)to authenticated;
